exercises.solution:
public class Main {
    public static void main(String[] args) {
        int[] t = {4, 8, 15, 16, 23, 42};
        int somme = 0;
        int max = t[0];
        for (int v : t) {
            somme += v;
            if (v > max) max = v;
        }
        System.out.println("Somme = " + somme);
        System.out.println("Max = " + max);
    }
}

